const writer=root.crypto?.randomUUID?.()||String(Date.now())+'-'+Math.random().toString(36).slice(2);
const pendingKey=id=>'pending:'+id+':'+writer;
const store=new C.StagedStore(browser,{pending:{put:value=>kv('put',pendingKey(value.libraryId),{...value,kind:'pending',writer}),remove:()=>kv('delete',pendingKey(store.repo.manifest.libraryId))},lock:async(name,fn)=>{if(!navigator.locks)throw C.fail('UNSUPPORTED','Web Locks is unavailable');return navigator.locks.request(name,fn)},onState:state=>{if(state.state==='pending')store.allowNavigation=false;root.dispatchEvent(new CustomEvent('anishelf-storage-state',{detail:state}));paintStatus()}});
