store.backupObject=(values=store.exportValues())=>({version:1,library:JSON.parse(values[C.LIB]||'[]'),watchHistory:JSON.parse(values[C.HISTORY]||'[]'),lists:JSON.parse(values[C.LISTS]||'[]'),seriesArchive:JSON.parse(values[C.ARCHIVE]||'[]'),preferences:Object.fromEntries(C.PREFS.filter(k=>values[k]!==undefined).map(k=>[k,values[k]]))});
store.download=(data,name)=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
