store.ready=new Promise((resolve,reject)=>{readyResolve=resolve;readyReject=reject});
function message(error){if(error.code==='CONFLICT')return say('资料库已在其他窗口或程序中改变。请先导出待保存数据，再重新载入；不会覆盖磁盘版本。','The library changed in another window or program. Export pending data, then reload. Disk data will not be overwritten.');if(error.code==='PERMISSION'||error.name==='NotAllowedError')return say('文件夹访问权限已失效，请点击重新授权。','Folder access expired. Reauthorize to continue.');return (error.message||String(error))}
