function paintStatus(){const node=document.getElementById('storageStatus');if(!node)return;node.hidden=store.mode!=='folder';node.dataset.state=store.state;node.textContent=store.state==='error'?say('保存失败：','Save failed: ')+message(store.error):store.state==='saved'?say('文件夹已保存','Saved to folder')+(store.repo?.assetWarnings.size?say(' · 部分图片缺失，可尝试补齐',' · Some images are missing; try completing the cache'):'')+(store.repo?.retentionWarning?say(' · 备份清理已暂停，原文件保留',' · Backup cleanup paused; files retained'):''):store.state==='saving'?say('正在保存到文件夹…','Saving to folder…'):say('更改待保存，请勿关闭','Changes pending. Keep this window open.');const settings=document.getElementById('folderStorageStatus');if(settings)settings.textContent=node.textContent}
store.paintStatus=paintStatus;
function gate(title,error,actions){let panel=document.getElementById('storageStartup');if(!panel){panel=document.createElement('section');panel.id='storageStartup';panel.className='storage-startup';panel.setAttribute('role','region');document.body.append(panel)}panel.replaceChildren();const h=document.createElement('h1');h.textContent=title;panel.append(h);const p=document.createElement('p');p.setAttribute('role','status');p.textContent=error;panel.append(p);const buttons=document.createElement('div');panel.append(buttons);for(const [label,action]of actions){const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=async()=>{if(gateBusy)return;gateBusy=true;for(const el of buttons.children)el.disabled=true;try{await action()}catch(e){p.textContent=message(e)}finally{gateBusy=false;for(const el of buttons.children)el.disabled=false}};buttons.append(b)}return panel}
function gateDone(){document.getElementById('storageStartup')?.remove();readyResolve()}
async function pendingRecords(id){return (await kv('all')).filter(r=>r?.kind==='pending'&&r.libraryId===id)}
async function resolvePending(repo,result){const records=await pendingRecords(result.manifest.libraryId);if(!records.length)return result;for(const r of records)if(C.sameValues(r.values,result.values)){await kv('delete','pending:'+r.libraryId+':'+r.writer);return resolvePending(repo,result)}return new Promise(resolve=>{
 const record=records[0],compatible=record.baseRevision===result.manifest.revision;
 gate(say('发现未保存的更改','Unsaved changes found'),compatible?say('上次的文件夹保存未完成。可恢复更改，或导出后使用磁盘版本。','The last save did not finish. Recover it, or export it and use disk data.'):say('待保存更改与磁盘版本冲突。请先导出；不会自动合并或覆盖。','Pending changes conflict with disk data. Export them first. No automatic merge or overwrite.'),[
 [say('导出待保存备份','Export pending backup'),async()=>store.download(store.backupObject(record.values),'anishelf-pending-'+record.writer+'.json')],
 ...(compatible?[[say('恢复并保存更改','Recover and save'),async()=>{C.validateValues(record.values);await navigator.locks.request('anishelf-folder-'+result.manifest.libraryId,()=>repo.commit(record.values,result.manifest.revision));await kv('delete','pending:'+record.libraryId+':'+record.writer);const fresh=await repo.load();resolve(await resolvePending(repo,fresh))}]]:[]),
 [say('放弃这份待保存更改，使用磁盘版本','Discard these pending changes; use disk'),async()=>{if(!confirm(say('确认放弃这份未保存更改？建议先导出。','Discard these unsaved changes? Export first if needed.')))return;await kv('delete','pending:'+record.libraryId+':'+record.writer);resolve(await resolvePending(repo,result))}]
 ]);
 })}
async function startFolder(request=false){const connection=await kv('get','connection');if(!connection?.handle)throw C.fail('PERMISSION',say('请重新选择原资料库文件夹。','Select the original library folder again.'));const repo=new C.FolderRepository(connection.handle);await repo.permission(request);let result=await repo.load();result=await resolvePending(repo,result);store.attach(repo,result.values);gateDone()}
async function boot(){let folder=false;try{folder=browser.getItem(MODE)==='folder'}catch{}if(!folder){gateDone();return}try{if(!store.supported())throw C.fail('UNSUPPORTED',say('当前环境不支持文件夹模式。请使用安全上下文中的 Edge 或 Chrome。','Folder mode needs Edge or Chrome in a secure context.'));await startFolder()}catch(error){gate(say('连接 AniShelf 资料库','Connect AniShelf library'),message(error),[
 [say('重新授权并连接','Reauthorize and connect'),()=>startFolder(true)],
 [say('重新选择原资料库文件夹','Choose original library folder'),async()=>{const dir=await showDirectoryPicker({mode:'readwrite',id:'anishelf-library'}),repo=new C.FolderRepository(dir);await repo.permission(true);await repo.load();await kv('put','connection',{handle:dir});await startFolder()}],
 [say('从文件夹备份恢复','Recover a folder backup'),()=>store.recoverStartupBackup()],
 [say('使用原浏览器副本','Use original browser copy'),async()=>{if(!confirm(say('将使用迁移前的浏览器副本，可能不是最新。文件夹和待保存记录不会删除。','The browser copy may be older. Folder files and pending recovery records will be kept.')))return;browser.setItem(MODE,'browser');gateDone()}]
 ])}}
store.recoverStartupBackup=async()=>{const connection=await kv('get','connection');if(!connection?.handle)throw Error('Choose the library folder first');const repo=new C.FolderRepository(connection.handle);await repo.permission(true);const backups=await repo.backups();if(!backups.length)throw Error(say('没有可恢复的备份','No restorable backups'));const number=prompt(say('输入要恢复的备份编号：\n','Enter a backup number:\n')+backups.map((r,i)=>(i+1)+'. '+r.date).join('\n'),'1');if(number===null)return;const chosen=backups[Number(number)-1];if(!chosen||!Number.isInteger(Number(number)))throw Error('Invalid backup number');await repo.load(chosen.raw);if(!confirm(say('确认恢复这个备份？当前索引会另外保留。','Restore this backup? The current manifest will be kept separately.')))return;await navigator.locks.request('anishelf-folder-'+repo.manifest.libraryId,async()=>{const current=await repo.manifestText();if(current)await C.write(repo.dir,'backups/broken-'+Date.now()+'.json',current);await C.write(repo.dir,'manifest.json',chosen.raw)});await startFolder()};
async function transfer(action){if(store.switching)throw Error('A transfer is already running');store.switching=true;const regions=[...document.querySelectorAll('.app,.sidebar,dialog')],previous=regions.map(el=>el.inert),overlay=document.createElement('div');overlay.className='storage-transfer';overlay.setAttribute('role','status');overlay.textContent=say('正在切换资料库，请勿关闭…','Transferring library. Keep this window open…');regions.forEach(el=>el.inert=true);document.body.append(overlay);try{return await action()}finally{store.switching=false;regions.forEach((el,i)=>el.inert=previous[i]);overlay.remove()}}
store.connect=async function(){if(!store.supported())throw C.fail('UNSUPPORTED',say('需要 Edge / Chrome、安全上下文、IndexedDB 和 Web Locks。当前 HTML 直接打开是否可用，以此检测为准。','Requires Edge / Chrome, a secure context, IndexedDB and Web Locks. Direct HTML support is determined by this check.'));
 // Picker must be called from the click before network or other long work.
 const dir=await showDirectoryPicker({mode:'readwrite',id:'anishelf-library'}),repo=new C.FolderRepository(dir);await repo.permission(true);return transfer(async()=>{if(store.mode==='folder')await store.flush();await db();const raw=await repo.manifestText();
 if(raw){await repo.load(raw);if(!confirm(say('此文件夹已有 AniShelf 资料库。打开它将切换当前显示的资料，原浏览器副本保留。','This folder contains an AniShelf library. Open it instead of the current library? The browser copy is kept.')))return;}
 else{if(!confirm(say('将当前资料完整复制到此文件夹并切换。原浏览器副本保留。请选择专用资料夹。','Copy current data into this dedicated folder and switch? The browser copy is kept.')))return;repo.cacheImages=false;const values=store.exportValues();values['anishelf-no-demo-v1']='1';await navigator.locks.request('anishelf-folder-new-'+dir.name,async()=>{if(await repo.manifestText())throw C.fail('CONFLICT','Folder initialized elsewhere');await repo.commit(values,null,{newLibrary:true})});await repo.load();}
 await kv('put','connection',{handle:dir});browser.setItem(MODE,'folder');store.navigate();});};
store.useBrowser=async function(){await store.flush();if(!confirm(say('切换至原浏览器副本（可能不是最新）。本地文件夹资料保持不变。','Switch to the original browser copy (possibly older)? Folder data is kept.')))return;browser.setItem(MODE,'browser');store.navigate()};
store.reauthorize=async()=>{if(!store.repo)throw Error('No folder');await store.repo.permission(true);await store.flush()};
store.reloadFolder=async()=>{if(store.dirty){await store.pending.put({libraryId:store.repo.manifest.libraryId,baseRevision:store.repo.manifest.revision,values:store.exportValues(),updatedAt:new Date().toISOString()});if(!confirm(say('重新载入后将进入待保存数据恢复流程。是否继续？','Reload and enter the pending-data recovery flow?')))return}store.navigate()};
store.makeBackup=async()=>{await store.flush();const repo=store.repo,m=repo.manifest;await navigator.locks.request('anishelf-folder-'+m.libraryId,async()=>{const current=repo.parseManifest(await repo.manifestText());if(current.revision!==m.revision||current.libraryId!==m.libraryId)throw C.fail('CONFLICT','Folder changed before backup');await C.write(repo.dir,'backups/'+m.revision+'.json',JSON.stringify(m));await repo.prune()});};
store.restoreBackup=async raw=>transfer(async()=>{await store.flush();const current=store.repo.manifest,probe=new C.FolderRepository(store.repo.dir);const result=await probe.load(raw);if(result.manifest.libraryId!==current.libraryId)throw C.fail('INVALID','Backup belongs to a different library');if(!confirm(say('恢复这个备份？当前版本会先保留为自动备份。','Restore this backup? The current version will be kept as an automatic backup.')))return;
 await store.pending.put({libraryId:current.libraryId,baseRevision:current.revision,values:result.values,updatedAt:new Date().toISOString()});try{await navigator.locks.request('anishelf-folder-'+current.libraryId,()=>store.repo.commit(result.values,current.revision));try{await store.pending.remove()}catch{}store.emit('saved');store.navigate()}catch(error){store.error=error;store.emit('error');throw error}
});
store.cacheImages=async onProgress=>{if(store.mode!=='folder')throw Error('Connect a folder first');await store.flush();store.repo.cacheImages=true;store.repo.cancelImages=false;store.repo.imageCount=0;store.repo.onImage=onProgress;store.repo.failedImages.clear();store.repo.written.clear();try{store.sequence++;store.emit('pending');await store.flush();return {failed:store.repo.assetErrors.length,cancelled:!!store.repo.cancelImages}}finally{store.repo.cacheImages=false;store.repo.onImage=null;store.repo.imageController=null}};
store.cancelImageDownload=()=>{if(!store.repo)return;store.repo.cancelImages=true;store.repo.imageController?.abort()};
root.addEventListener('beforeunload',event=>{if((store.dirty||store.switching)&&!store.allowNavigation){event.preventDefault();event.returnValue=''}});
