// URLs are kept when the page enters the back-forward cache; no eager image preload.
// Cross-window notification is advisory; disk revision checks remain authoritative.
try{if(typeof BroadcastChannel==='function'){const channel=new BroadcastChannel('anishelf-folder-storage-v1');const originalEmit=store.emit.bind(store);store.emit=state=>{originalEmit(state);if(state==='saved'&&store.repo)channel.postMessage({id:store.repo.manifest.libraryId,revision:store.repo.manifest.revision})};channel.onmessage=event=>{if(store.mode==='folder'&&event.data.id===store.repo.manifest.libraryId&&event.data.revision!==store.repo.manifest.revision){store.error=C.fail('CONFLICT',say('其他窗口已修改资料库。','Another window changed the library.'));store.emit('error')}}}}catch{/* Notifications are optional; disk checks and Web Locks remain authoritative. */}
